code='''from collections import Counter, defaultdict, deque


def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            queue = deque([(r, c)])
            while queue:
                x, y = queue.popleft()
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx, ny))
                        cells.add((nx, ny))
                        queue.append((nx, ny))
            result.append((color, cells))
    return result


def _normalized(points):
    r0 = min(r for r, c in points)
    c0 = min(c for r, c in points)
    return frozenset((r - r0, c - c0) for r, c in points)


def _shape_key(points):
    forms = []
    for reflect in (1, -1):
        for turns in range(4):
            transformed = []
            for r, c in points:
                x, y = r, c * reflect
                for _ in range(turns):
                    x, y = y, -x
                transformed.append((x, y))
            forms.append(tuple(sorted(_normalized(transformed))))
    return min(forms)


def _l_stem(points):
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    for r in (r0, r1):
        for c in (c0, c1):
            expected = {(r, x) for x in range(c0, c1 + 1)} | {(x, c) for x in range(r0, r1 + 1)}
            if points == expected and len(expected) > 2:
                return c
    return None


def transform(grid):
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    objects = _components(grid, background)
    keys = [(i, color, cells, _l_stem(cells)) for i, (color, cells) in enumerate(objects) if _l_stem(cells) is not None]
    if not keys:
        return [row[:] for row in grid]
    key_i, key_color, key_cells, stem = max(keys, key=lambda item: len(item[2]))

    groups = defaultdict(list)
    for i, (color, cells) in enumerate(objects):
        if i != key_i:
            groups[_shape_key(cells)].append((color, cells))

    choices = []
    for group in groups.values():
        left = [obj for obj in group if max(c for r, c in obj[1]) < stem]
        right = [obj for obj in group if min(c for r, c in obj[1]) > stem]
        for a in left:
            for b in right:
                if len(a[1]) == len(b[1]):
                    choices.append((len(a[1]), a[1]))
    if not choices:
        return [row[:] for row in grid]
    target = max(choices, key=lambda item: item[0])[1]
    result = [row[:] for row in grid]
    for r, c in target:
        result[r][c] = key_color
    return result
